impl LifecycleKind {
    fn from_byte(value: u8) -> Result<Self, ProgramError> {
        match value {
            0 => Ok(Self::Proof),
            1 => Ok(Self::Public),
            _ => Err(ProgramError::InvalidInstructionData),
        }
