fn readonly_meta_ok(
    owner: &Pubkey,
    expected: &Pubkey,
    is_signer: bool,
    is_writable: bool,
    executable: bool,
) -> ProgramResult {
    if owner != expected || is_signer || is_writable || executable {
        return Err(ProgramError::InvalidAccountData);
    }
    Ok(())
}

